class Solution {
public:
    vector<int> postorder(Node* root) {
        vector<int> result;
        helper(root, result);
        return result;
    }
private:
    void helper(Node* node, vector<int>& result) {
        if (!node) return;
        for (Node* child : node->children) {
            helper(child, result);
        }
        result.push_back(node->val);
    }
};
